                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.qcom_replen_4_July2025 as Select a.*from ( WITH warehouse_rank AS ( SELECT a.facility, REPLACE( REPLACE( REPLACE(UPPER(a.SKU),\'-48\',\'-7XL\'), \'-50\',\'-8XL\'), \'-XXXL\', \'-3XL\') AS SKU, CASE WHEN a.units_on_hand <=1 THEN 0 ELSE a.units_on_hand -1 - c.SOCIALISTIC END AS units_on_hand, ROW_NUMBER() OVER (PARTITION BY a.SKU ORDER BY units_on_hand DESC) AS warehouse_rank FROM SNITCH_DB.MAPLEMONK.LIVE_INV_WAREHOUSE_offline_replen a left join snitch_db.maplemonk.store_replen_6_May2025 c on a.sku = c.SKU_CODE and a.facility = c.facility ), replen_requirements AS ( SELECT SKU_CODE, pareto, REPLEN_UNITS, REPLEN_UNITS as total_replen_req, ROW_NUMBER() OVER (PARTITION BY SKU_CODE ORDER BY pareto ASC) AS replen_order FROM snitch_db.maplemonk.qcom_replen_3_July2025 ), warehouse_1 AS ( SELECT r.SKU_CODE, r.pareto, r.REPLEN_UNITS, r.total_replen_req, w.facility, w.units_on_hand, r.replen_order, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM replen_requirements r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 1 ), warehouse_2 AS ( SELECT r.SKU_CODE, r.pareto, r.total_replen_req, w.facility, w.units_on_hand, r.replen_order, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM (SELECT SKU_CODE, pareto, remaining_units AS REPLEN_UNITS, total_replen_req, replen_order FROM warehouse_1 WHERE remaining_units > 0) r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 2 ), warehouse_3 AS ( SELECT r.SKU_CODE, r.pareto, w.facility, w.units_on_hand, r.replen_order, r.total_replen_req, CASE 